import { ApiProperty, ApiPropertyOptional } from "@nestjs/swagger";
import { Type } from "class-transformer";
import {
  CollectionKind,
  CourseType,
  SimulatedOutcome,
  StaffRole,
} from "../generated/prisma/enums";
import {
  IsBoolean,
  IsDateString,
  IsIn,
  IsInt,
  IsOptional,
  IsString,
  IsEmail,
  IsUUID,
  IsUrl,
  Max,
  MaxLength,
  Min,
  MinLength,
  ValidateIf,
  IsArray,
  ArrayMinSize,
  ArrayUnique,
  ArrayMaxSize,
  Matches,
  IsObject,
} from "class-validator";
// Allowed values come from the database enums generated by Prisma.
export const provisioningOutcomes = Object.values(SimulatedOutcome);
export type ProvisioningOutcome = SimulatedOutcome;
const courseTypes = Object.values(CourseType);
export const slugPattern = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const staffRoleValues = Object.values(StaffRole);
export class RegistrationDto {
  @ApiProperty() @IsUUID() offeringId!: string;
}
export class DecisionDto {
  @ApiProperty({ enum: ["approved", "declined"] })
  @IsIn(["approved", "declined"])
  decision!: "approved" | "declined";
}
export class OfferingDto {
  @ApiProperty() @IsString() @MinLength(3) @MaxLength(120) title!: string;
  @ApiProperty({ enum: ["Technology", "Leadership", "Healthcare", "Ministry"] })
  @IsIn(["Technology", "Leadership", "Healthcare", "Ministry"])
  category!: string;
  @ApiProperty() @IsString() @MinLength(10) @MaxLength(240) summary!: string;
  @ApiProperty()
  @IsString()
  @MinLength(20)
  @MaxLength(4000)
  description!: string;
  @ApiProperty() @IsString() @MinLength(3) @MaxLength(100) format!: string;
  @ApiProperty({ enum: courseTypes })
  @IsIn(courseTypes)
  courseType!: CourseType;
  @ApiPropertyOptional({
    description: "Required for cohort courses; omit for self-paced courses.",
  })
  @ValidateIf((o) => o.courseType === "cohort" || o.startDate != null)
  @IsDateString({ strict: true })
  startDate?: string;
  @ApiPropertyOptional({
    description: "Required for cohort courses; omit for self-paced courses.",
  })
  @ValidateIf((o) => o.courseType === "cohort" || o.endDate != null)
  @IsDateString({ strict: true })
  endDate?: string;
  @ApiProperty() @IsInt() @Min(1) @Max(10000) capacity!: number;
  @ApiProperty() @IsInt() @Min(0) @Max(1000000) priceCents!: number;
  @ApiProperty() @IsBoolean() approvalRequired!: boolean;
  @ApiPropertyOptional({
    default: 7,
    description:
      "Days an approval stays valid before the learner must reserve.",
  })
  @IsOptional()
  @IsInt()
  @Min(1)
  @Max(365)
  approvalValidDays?: number;
  @ApiPropertyOptional({
    default: 7,
    description:
      "Scheduled courses: days after the start date when enrollment closes.",
  })
  @IsOptional()
  @IsInt()
  @Min(0)
  @Max(365)
  enrollmentCloseDays?: number;
  @ApiPropertyOptional({
    description: "HTTPS link to the mapped Canvas course.",
  })
  @IsOptional()
  @IsUrl({ protocols: ["https"], require_protocol: true })
  @MaxLength(500)
  canvasCourseUrl?: string;
}
export class OfferingSettingsDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
  @ApiProperty({ minimum: 1, maximum: 365 })
  @IsInt()
  @Min(1)
  @Max(365)
  approvalValidDays!: number;
  @ApiProperty({ minimum: 0, maximum: 365 })
  @IsInt()
  @Min(0)
  @Max(365)
  enrollmentCloseDays!: number;
  @ApiPropertyOptional({
    nullable: true,
    description: "HTTPS link to the mapped Canvas course; null removes it.",
  })
  @IsOptional()
  @IsUrl({ protocols: ["https"], require_protocol: true })
  @MaxLength(500)
  canvasCourseUrl?: string | null;
}
export class PublishDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
}
export class QueryDto {
  @ApiPropertyOptional()
  @IsOptional()
  @IsString()
  @MaxLength(120)
  search?: string;
  @ApiPropertyOptional({
    enum: ["Technology", "Leadership", "Healthcare", "Ministry"],
  })
  @IsOptional()
  @IsIn(["Technology", "Leadership", "Healthcare", "Ministry"])
  category?: string;
  @ApiPropertyOptional({ description: "Published collection or pathway slug" })
  @IsOptional()
  @Matches(slugPattern)
  collection?: string;
}

export class DemoUserDto {
  @ApiProperty({
    example: "learner@example.com",
    description: "Mock sign-in only; no password accepted.",
  })
  @IsEmail()
  @MaxLength(254)
  email!: string;
}
export class SimulationDto {
  @ApiProperty({
    enum: provisioningOutcomes,
    description:
      "PROTOTYPE ONLY: outcome applied to provisioning queued after this change.",
  })
  @IsIn(provisioningOutcomes)
  provisioningOutcome!: ProvisioningOutcome;
}
export class ExceptionActionDto {
  @ApiProperty({
    description: "Why staff are taking this action; recorded in the audit log.",
    minLength: 10,
    maxLength: 500,
  })
  @IsString()
  @MinLength(10)
  @MaxLength(500)
  reason!: string;
}
export class OfferingEditDto extends OfferingDto {
  @ApiProperty({ description: "Current version, for conflict detection." })
  @IsInt()
  @Min(1)
  version!: number;
  @ApiPropertyOptional({
    description:
      "Required (10–500 characters) when the offering is published; recorded in the audit log.",
  })
  @IsOptional()
  @IsString()
  @MaxLength(500)
  reason?: string;
}
export class UnpublishDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
  @ApiProperty({ minLength: 10, maxLength: 500 })
  @IsString()
  @MinLength(10)
  @MaxLength(500)
  reason!: string;
}
export class StaffSessionDto {
  @ApiProperty({ example: "approver@cuce.test" })
  @IsEmail()
  @MaxLength(254)
  email!: string;
}
export class StaffMemberDto {
  @ApiProperty() @IsEmail() @MaxLength(254) email!: string;
  @ApiProperty() @IsString() @MinLength(2) @MaxLength(120) displayName!: string;
  @ApiProperty({ enum: staffRoleValues, isArray: true })
  @IsArray()
  @ArrayMinSize(1)
  @ArrayUnique()
  @IsIn(staffRoleValues, { each: true })
  roles!: StaffRole[];
}
export class StaffUpdateDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
  @ApiProperty() @IsString() @MinLength(2) @MaxLength(120) displayName!: string;
  @ApiProperty({ enum: staffRoleValues, isArray: true })
  @IsArray()
  @ArrayMinSize(1)
  @ArrayUnique()
  @IsIn(staffRoleValues, { each: true })
  roles!: StaffRole[];
  @ApiProperty() @IsBoolean() active!: boolean;
}
export class LearnerAccessDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
  @ApiProperty({ description: "true to reactivate, false to deactivate" })
  @IsBoolean()
  active!: boolean;
  @ApiProperty({ minLength: 10, maxLength: 500 })
  @IsString()
  @MinLength(10)
  @MaxLength(500)
  reason!: string;
}
export class LearnerQueryDto {
  @ApiPropertyOptional()
  @IsOptional()
  @IsString()
  @MaxLength(254)
  search?: string;
}
export class DashboardQueryDto {
  @ApiPropertyOptional({
    enum: [7, 30, 90, 365, 0],
    description: "Days back from today; 0 means all time. Default 30.",
  })
  @IsOptional()
  @Type(() => Number)
  @IsIn([7, 30, 90, 365, 0])
  days?: number;
  @ApiPropertyOptional() @IsOptional() @IsUUID() offeringId?: string;
}

// Collections and pathways (decisions F3 and F4). Kind and slug are fixed at creation.
export class CollectionEditDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
  @ApiProperty() @IsString() @MinLength(3) @MaxLength(120) title!: string;
  @ApiProperty() @IsString() @MinLength(10) @MaxLength(500) summary!: string;
  @ApiProperty({
    type: [String],
    description:
      "Offering IDs in display order; for pathways, the recommended order",
  })
  @IsArray()
  @ArrayMaxSize(50)
  @ArrayUnique()
  @IsUUID(undefined, { each: true })
  offeringIds!: string[];
}
export class CollectionDto {
  @ApiProperty({ enum: Object.values(CollectionKind) })
  @IsIn(Object.values(CollectionKind))
  kind!: CollectionKind;
  @ApiProperty() @IsString() @MinLength(3) @MaxLength(120) title!: string;
  @ApiPropertyOptional({
    description: "Public URL segment; derived from the title when omitted",
  })
  @IsOptional()
  @MaxLength(80)
  @Matches(slugPattern, {
    message: "slug must be lowercase letters and numbers joined by hyphens",
  })
  slug?: string;
  @ApiProperty() @IsString() @MinLength(10) @MaxLength(500) summary!: string;
  @ApiProperty({ type: [String] })
  @IsArray()
  @ArrayMaxSize(50)
  @ArrayUnique()
  @IsUUID(undefined, { each: true })
  offeringIds!: string[];
}
export class SavedCourseDto {
  @ApiProperty({ description: "true to save the course, false to remove it" })
  @IsBoolean()
  saved!: boolean;
}
export class FollowDto {
  @ApiProperty({
    description:
      "true to follow the pathway, false to stop; following registers nothing",
  })
  @IsBoolean()
  following!: boolean;
}
// Staff picks for the learner Explore tab, in display order; empty spots fill automatically.
export class ExploreDto {
  @ApiProperty({ type: [String], description: "Up to 5 published courses" })
  @IsArray()
  @ArrayMaxSize(5)
  @ArrayUnique()
  @IsUUID(undefined, { each: true })
  courses!: string[];
  @ApiProperty({ type: [String], description: "Up to 3 published collections" })
  @IsArray()
  @ArrayMaxSize(3)
  @ArrayUnique()
  @IsUUID(undefined, { each: true })
  collections!: string[];
  @ApiProperty({ type: [String], description: "Up to 3 published pathways" })
  @IsArray()
  @ArrayMaxSize(3)
  @ArrayUnique()
  @IsUUID(undefined, { each: true })
  pathways!: string[];
}
export class RefundReasonDto {
  @ApiProperty({ description: "Why (10-500 characters); visible to Finance" })
  @IsString()
  @MinLength(10)
  @MaxLength(500)
  reason!: string;
}
// Sales pages: the page body is checked block by block in src/server/sales-pages.ts.
export class SalesPageDto {
  @ApiProperty({ description: "Current version; 0 creates the page" })
  @IsInt()
  @Min(0)
  version!: number;
  @ApiProperty({
    description:
      "{ blocks: [...], seo: { title, description } }; block types hero, text, outcomes, instructor, testimonial, faq",
  })
  @IsObject()
  page!: Record<string, unknown>;
}
// Images for sales pages, sent as base64 JSON through the website's API proxy.
export class MediaUploadDto {
  @ApiProperty() @IsString() @MinLength(1) @MaxLength(200) fileName!: string;
  @ApiProperty({ enum: ["image/png", "image/jpeg", "image/webp", "image/gif"] })
  @IsIn(["image/png", "image/jpeg", "image/webp", "image/gif"])
  contentType!: string;
  @ApiProperty({ description: "Base64 file contents, up to 5 MB decoded" })
  @IsString()
  @MaxLength(7_000_000)
  data!: string;
}
export class SalesPageRestoreDto {
  @ApiProperty() @IsInt() @Min(1) version!: number;
  @ApiProperty({ description: "Published revision to copy into the draft" })
  @IsInt()
  @Min(1)
  revision!: number;
}
